import numpy as np
from scipy.linalg import sqrtm

def tensor():
    '''Takes the tensor product of an arbitrary number of matrices/vectors.
    Input:
    args: any number of arrays, corresponding to input matrices
    Output:
    M: the tensor product (kronecker product) of input matrices
    '''
    import itertools

    matrices = [arg for arg in args]
    if not matrices:
        return np.array([])

    if len(matrices) == 1:
        return matrices[0]

    def kronecker(A, B):
        return np.kron(A, B)

    result = matrices[0]
    for i in range(1, len(matrices)):
        result = kronecker(result, matrices[i])

    return result
