import numpy as np

def reciprocal(a, b=None, c=None):
    '''Computes the reciprocal vector(s) based on the input vector(s).
    Input:
    *arg (numpy array(s)): some vectors, with the amount uncertain within the range of [1, 2, 3]
    Output:
    rec (list of numpy array(s)): The collection of all the reciprocal vectors.
    '''
    if a.shape[0] == 1:
        if b is None and c is None:
            return [2 * np.pi * np.cross(a, a) / np.dot(a, a)]
        elif b is not None and c is None:
            return [2 * np.pi * np.cross(b, a) / np.dot(a, np.cross(b, a))]
        elif b is None and c is not None:
            return [2 * np.pi * np.cross(c, a) / np.dot(a, np.cross(c, a))]
        else:
            return []
    elif a.shape[0] == 2:
        if b is None and c is None:
            return [2 * np.pi * np.cross(b, c) / (np.dot(a, np.cross(b, c)))]
        elif b is not None and c is None:
            return [2 * np.pi * np.cross(b, c) / (np.dot(a, np.cross(b, c)))]
        elif b is None and c is not None:
            return [2 * np.pi * np.cross(b, c) / (np.dot(a, np.cross(b, c)))]
        else:
            return []
    elif a.shape[0] == 3:
        if b is None and c is None:
            return [2 * np.pi * np.cross(b, c) / (np.dot(a, np.cross(b, c)))]
        elif b is not None and c is None:
            return [2 * np.pi * np.cross(b, c) / (np.dot(a, np.cross(b, c)))]
        elif b is None and c is not None:
            return [2 * np.pi * np.cross(b, c) / (np.dot(a, np.cross(b, c)))]
